-- mod-temucraft-world: a .tele point on every new Forever map (tools/forever_tele.py), for staff to visit and
-- test them. The points come from the terrain (middle of the map), not from real start points, which the
-- Forever data does not have. Names start with F and the map id, e.g. .tele F2784DemonFallCanyon.
DELETE FROM `game_tele` WHERE `name` IN ('F2720TheSearingBasin', 'F2784DemonFallCanyon', 'F2789TheTaintedScar', 'F2791StormCliffs', 'F2804TheCrystalVale', 'F2806ShadowHold', 'F2807BurningofAndorhal', 'F2817StarfallBarrowDen', 'F2832NightmareGrove', 'F2853DeadwindPass', 'F2856ScarletEnclave', 'F2868EasternPlaguelandsScarletRaidPhase', 'F2875KarazhanCrypts', 'F2902TheScarabDais', 'F2921Naxxramas', 'F2959CityofDalaran', 'F2980DalaranCity', 'F2991ZephrasIsle', 'F2995HyjalCrater', 'F2996WarsongGulchWinter', 'F2998ExcavationSiteWetlands', 'F2999RuinsofLordaeron', 'F3002HalfPintTavern', 'F3005BattleforGilneas', 'F3021EasternKingdomsPreserved', 'F3065TheHallofThanes', 'F3104nothingtoseehere');
